   194→// ============================================================================
   195→// Part 3: 라운드-로빈 스케줄러
   196→// ============================================================================
   197→
   198→/// 스케줄러 큐의 노드
   199→pub struct ReadyQueueNode {
   200→    /// 프로세스 ID
   201→    pub pid: u32,
   202→
   203→    /// 프로세스 컨텍스트
   204→    pub context: ProcessContext,
   205→
   206→    /// 타임 슬라이스 (밀리초)
   207→    pub time_slice_ms: u32,
   208→
   209→    /// 사용된 시간 (밀리초)
   210→    pub used_time_ms: u32,
   211→}
   212→
   213→impl ReadyQueueNode {
   214→    pub fn new(pid: u32, context: ProcessContext, time_slice_ms: u32) -> Self {
   215→        ReadyQueueNode {
   216→            pid,
   217→            context,
   218→            time_slice_ms,
   219→            used_time_ms: 0,
   220→        }
   221→    }
   222→
   223→    pub fn has_time_remaining(&self) -> bool {
   224→        self.used_time_ms < self.time_slice_ms
   225→    }
   226→
   227→    pub fn consume_time(&mut self, duration_ms: u32) {
   228→        self.used_time_ms += duration_ms;
   229→    }
   230→
   231→    pub fn reset_time(&mut self) {
   232→        self.used_time_ms = 0;
   233→    }
   234→
   235→    pub fn time_remaining(&self) -> u32 {
   236→        if self.used_time_ms < self.time_slice_ms {
   237→            self.time_slice_ms - self.used_time_ms
   238→        } else {
   239→            0
   240→        }
   241→    }
   242→}
   243→
   244→/// 라운드-로빈 스케줄러
   245→pub struct RoundRobinScheduler {
   246→    /// Ready 큐 (FIFO)
   247→    pub ready_queue: Vec<ReadyQueueNode>,
   248→
   249→    /// 현재 실행 중인 프로세스 인덱스
   250→    pub current_index: Option<usize>,
   251→
   252→    /// 기본 타임 슬라이스 (4ms)
   253→    pub default_time_slice_ms: u32,
   254→
   255→    /// 스케줄러 틱 카운트
   256→    pub tick_count: u32,
   257→
   258→    /// 컨텍스트 전환 횟수
   259→    pub context_switch_count: u32,
   260→}
   261→
   262→impl RoundRobinScheduler {
   263→    pub fn new() -> Self {
   264→        RoundRobinScheduler {
   265→            ready_queue: Vec::new(),
   266→            current_index: None,
   267→            default_time_slice_ms: 4,  // 4ms 타임 슬라이스
   268→            tick_count: 0,
   269→            context_switch_count: 0,
   270→        }
   271→    }
   272→
   273→    pub fn add_process(&mut self, pid: u32, context: ProcessContext) {
   274→        let node = ReadyQueueNode::new(pid, context, self.default_time_slice_ms);
   275→        self.ready_queue.push(node);
   276→
   277→        // 첫 프로세스면 현재 실행 중인 것으로 설정
   278→        if self.current_index.is_none() {
   279→            self.current_index = Some(0);
   280→        }
   281→    }
   282→
   283→    pub fn schedule_next(&mut self) -> Option<(u32, ProcessContext)> {
   284→        if self.ready_queue.is_empty() {
   285→            return None;
   286→        }
   287→
   288→        // 현재 프로세스의 타임 슬라이스가 끝났으면 다음 프로세스로 전환
   289→        if let Some(current) = self.current_index {
   290→            let queue_len = self.ready_queue.len();
   291→
   292→            // 현재 프로세스의 시간 초기화
   293→            self.ready_queue[current].reset_time();
   294→
   295→            // 다음 프로세스로 이동
   296→            let next_index = (current + 1) % queue_len;
   297→            self.current_index = Some(next_index);
   298→            self.context_switch_count += 1;
   299→
   300→            let node = &self.ready_queue[next_index];
   301→            let context = node.context.clone();
   302→            return Some((node.pid, context));
   303→        }
   304→
   305→        None
   306→    }
   307→
   308→    pub fn get_current_process(&self) -> Option<(u32, &ProcessContext)> {
   309→        if let Some(index) = self.current_index {
   310→            if index < self.ready_queue.len() {
   311→                let node = &self.ready_queue[index];
   312→                return Some((node.pid, &node.context));
   313→            }
   314→        }
   315→        None
   316→    }
   317→
   318→    pub fn consume_time(&mut self, duration_ms: u32) {
   319→        if let Some(index) = self.current_index {
   320→            self.ready_queue[index].consume_time(duration_ms);
   321→        }
   322→        self.tick_count += 1;
   323→    }
   324→
   325→    pub fn queue_length(&self) -> usize {
   326→        self.ready_queue.len()
   327→    }
   328→
   329→    pub fn print_queue_status(&self) {
   330→        println!("\n📊 Ready Queue Status:");
   331→        println!("  Total Processes: {}", self.ready_queue.len());
   332→        println!("  Context Switches: {}", self.context_switch_count);
   333→        println!("  Total Ticks: {}", self.tick_count);
   334→        println!("\n  Queue Contents:");
   335→
   336→        for (idx, node) in self.ready_queue.iter().enumerate() {
   337→            let status = if self.current_index == Some(idx) {
   338→                "▶️ RUNNING"
   339→            } else {
   340→                "⏸️  WAITING"
   341→            };
   342→
   343→            println!("    [{}] PID {} - {} (Time: {}/{}ms)",
   344→                     idx, node.pid, status,
   345→                     node.used_time_ms, node.time_slice_ms);
   346→        }
   347→    }
   348→}
