# FreeLang OS Kernel: 실제 동작 구현 로드맵

**목표**: 시뮬레이션 → 실제 x86-64 OS (QEMU에서 부팅 및 동작)

---

## 📋 Phase 0: 현재 상태 분석

### ✅ 이미 완성된 것
- bootloader.fl: 메모리 관리 알고리즘 (물리/가상/힙)
- kernel.fl: 프로세스 관리 구조
- scheduler.fl: Context switching 로직
- interrupt.fl: IDT 구조

### ❌ 부족한 것
- 실제 x86-64 부트로더 (GRUB/multiboot 호환)
- 실제 메모리 레이아웃 설정
- 실제 GDT/IDT 어셈블리
- 실제 인터럽트 처리 루틴 (어셈블리)
- Context switching 어셈블리 코드
- 실제 하드웨어 타이머 상호작용
- QEMU 시뮬레이터 설정

---

## 🏗️ Phase 1: Bootloader 재구성 (1-2주)

### 1.1 Multiboot2 Bootloader 작성

**목표**: QEMU에서 부팅 가능하도록 만들기

**파일**: `src/boot.s` (x86-64 어셈블리)

```asm
; src/boot.s - x86-64 Bootloader
[bits 32]  ; 32-bit 모드에서 시작

MULTIBOOT2_HEADER_MAGIC     equ 0xe85250d6
MULTIBOOT_ARCHITECTURE_I386 equ 0
MULTIBOOT2_HEADER_TAG_END   equ 0

section .multiboot_header
align 8
    dd MULTIBOOT2_HEADER_MAGIC
    dd MULTIBOOT_ARCHITECTURE_I386
    dd (header_end - header_start)
    dd -(MULTIBOOT2_HEADER_MAGIC + MULTIBOOT_ARCHITECTURE_I386 + (header_end - header_start))

    ; 태그 (선택사항)
    dw 0
    dw 0
    dd 8

header_start:
header_end:

section .text
extern long_mode_start

global _start
_start:
    mov esp, stack_top
    call check_multiboot
    call check_cpuid
    call check_long_mode
    call setup_page_tables
    call enable_paging

    ; 64-bit 모드 전환
    lgdt [gdt64.pointer]
    jmp gdt64.code:long_mode_start

check_multiboot:
    cmp eax, 0x36d76289
    jne .no_multiboot
    ret
.no_multiboot:
    mov al, "M"
    jmp error

check_cpuid:
    pushfd
    pop eax
    mov ecx, eax
    xor eax, 0x200000
    push eax
    popfd
    pushfd
    pop eax
    cmp eax, ecx
    je .no_cpuid
    ret
.no_cpuid:
    mov al, "C"
    jmp error

check_long_mode:
    mov eax, 0x80000000
    cpuid
    cmp eax, 0x80000001
    jb .no_long_mode

    mov eax, 0x80000001
    cpuid
    test edx, 1 << 29
    jz .no_long_mode
    ret
.no_long_mode:
    mov al, "L"
    jmp error

setup_page_tables:
    mov eax, p4_table
    or eax, 0b11
    mov [p4_table], eax

    mov eax, p3_table
    or eax, 0b11
    mov [p4_table + 0], eax

    mov eax, p2_table
    or eax, 0b11
    mov [p3_table + 0], eax

    ; 2MB 페이지 설정 (0x200000부터 시작)
    mov ecx, 0
.loop:
    mov eax, 0x200000
    add eax, ecx
    shl ecx, 21
    or eax, 0b10000011  ; 쓰기 가능, 존재, 큰 페이지
    mov [p2_table + ecx], eax

    inc ecx
    cmp ecx, 512
    jne .loop

    ret

enable_paging:
    mov eax, p4_table
    mov cr3, eax

    mov eax, cr4
    or eax, 1 << 5
    mov cr4, eax

    mov ecx, 0xC0000080
    rdmsr
    or eax, 1 << 8
    wrmsr

    mov eax, cr0
    or eax, 1 << 31
    or eax, 1 << 16
    mov cr0, eax

    ret

error:
    mov dword [0xb8000], 0x4f524f45
    mov dword [0xb8004], 0x4f3a4f52
    mov dword [0xb8008], 0x4f204f20
    mov byte [0xb800a], al
    hlt

section .bss
align 4096
p4_table: resq 512
p3_table: resq 512
p2_table: resq 512
stack_bottom:
    resb 4096 * 4
stack_top:

section .rodata
gdt64:
    dq 0
.code: equ $ - gdt64
    dq (1<<43) | (1<<47) | (1<<53)
.pointer:
    dw $ - gdt64 - 1
    dq gdt64
```

### 1.2 Long Mode 진입점

**파일**: `src/long_mode_init.asm`

```asm
; src/long_mode_init.asm
[bits 64]

extern kernel_main

global long_mode_start
long_mode_start:
    mov rax, kernel_main
    call rax
    hlt
```

### 1.3 Cargo.toml 설정

```toml
[package]
name = "freelang-kernel"
version = "0.1.0"
edition = "2021"

[dependencies]
x86_64 = "0.14"
volatile = "0.4"

[profile.dev]
panic = "abort"
lto = true

[[bin]]
name = "kernel"
path = "src/main.rs"

[build]
target = "x86_64-unknown-linux-gnu"
```

