/// EOI (End of Interrupt) 신호 전송
fn send_eoi(irq: u8) {
    use x86_64::instructions::port::Port;

    unsafe {
        if irq >= 8 {
            let mut port = Port::new(0xA0u16);
            port.write(0x20u8);  // slave EOI
        }

        let mut port = Port::new(0x20u16);
        port.write(0x20u8);  // master EOI
    }
}

