#[panic_handler]
fn panic(info: &PanicInfo) -> ! {
    writeln!(
        WRITER.lock(),
        "🔴 KERNEL PANIC: {}",
        info
    ).unwrap();

    println!("PANIC: {}", info);

    loop {
        unsafe { asm!("hlt"); }
    }
}

